COMMENT ON TABLE svc.efile_movement IS 'Movement of an e-file from desk to desk';

CREATE TABLE svc.physical_dispatch (
  dispatch_id serial PRIMARY KEY,
  department_id int NOT NULL,
  direction varchar(8) NOT NULL,
  item_type varchar(10) NOT NULL,
  description text NOT NULL,
  party text NOT NULL,
  ref_no varchar(20) NOT NULL,
  dated date NOT NULL,
  handled_by_account_id int NOT NULL
);
COMMENT ON TABLE svc.physical_dispatch IS 'Physical file or item despatched or received by a department';

CREATE TABLE svc.physical_item_movement (
  item_movement_id serial PRIMARY KEY,
  dispatch_id int NOT NULL,
  to_account_id int NOT NULL,
  status varchar(10) NOT NULL,
  moved_at timestamptz NOT NULL
);
COMMENT ON TABLE svc.physical_item_movement IS 'Where a physical item is now';

CREATE TABLE gh.guesthouse (
  guesthouse_id serial PRIMARY KEY,
  name text NOT NULL,
  location text NOT NULL
);
COMMENT ON TABLE gh.guesthouse IS 'Guest houses on campus';

CREATE TABLE gh.gh_room (
  gh_room_id serial PRIMARY KEY,
  guesthouse_id int NOT NULL,
  room_no varchar(8) NOT NULL,
  room_type varchar(10) NOT NULL,
  rate_per_day numeric(8,2) NOT NULL
);
COMMENT ON TABLE gh.gh_room IS 'Rooms of a guest house';

CREATE TABLE gh.gh_booking (
  booking_id serial PRIMARY KEY,
  gh_room_id int NOT NULL,
  booked_by_account_id int NOT NULL,
  guest_name text NOT NULL,
  purpose text NOT NULL,
  check_in date NOT NULL,
  check_out date NOT NULL,
  status varchar(10) NOT NULL,
  charges numeric(8,2) NOT NULL
);
COMMENT ON TABLE gh.gh_booking IS 'Guest house bookings';

CREATE TABLE cdc.company (
  company_id serial PRIMARY KEY,
  name text NOT NULL UNIQUE,
  sector text NOT NULL
);
COMMENT ON TABLE cdc.company IS 'Recruiting companies';

CREATE TABLE cdc.job_posting (
  posting_id serial PRIMARY KEY,
  company_id int NOT NULL,
  role_title text NOT NULL,
  posting_type varchar(10) NOT NULL,
  ctc_lakhs numeric(6,2) NOT NULL,
  min_cgpa numeric(4,2),
  deadline date NOT NULL
);
COMMENT ON TABLE cdc.job_posting IS 'Placement and internship postings';

CREATE TABLE cdc.job_application (
  job_application_id serial PRIMARY KEY,
  posting_id int NOT NULL,
  student_id int NOT NULL,
  status varchar(10) NOT NULL,
  applied_at timestamptz NOT NULL
);
COMMENT ON TABLE cdc.job_application IS 'Student applications to postings';

CREATE TABLE cdc.offer (
  offer_id serial PRIMARY KEY,
  job_application_id int NOT NULL UNIQUE,
  ctc_offered_lakhs numeric(6,2) NOT NULL,
  offered_on date NOT NULL,
  accepted boolean
);
COMMENT ON TABLE cdc.offer IS 'Offers made to students';

CREATE TABLE sys.menu_module (
  module_id serial PRIMARY KEY,
  name text NOT NULL UNIQUE
);
COMMENT ON TABLE sys.menu_module IS 'Top-level modules (Academic, Accounts, Guest House, CDC)';

CREATE TABLE sys.menu_item (
  menu_id serial PRIMARY KEY,
  module_id int NOT NULL,
  group_name text NOT NULL,
  title text NOT NULL,
  url text NOT NULL,
  description text,
  sort_order smallint NOT NULL,
  is_active boolean NOT NULL
);
COMMENT ON TABLE sys.menu_item IS 'Every menu link in the ERP';

CREATE TABLE sys.role_menu_access (
  role_id int,
  menu_id int,
  PRIMARY KEY (role_id, menu_id)
);
COMMENT ON TABLE sys.role_menu_access IS 'Which role sees which menu link';

CREATE TABLE sys.audit_event (
  event_id bigserial PRIMARY KEY,
  account_id int,
  table_name text NOT NULL,
  record_pk text NOT NULL,
  action varchar(8) NOT NULL,
  at timestamptz NOT NULL
);
COMMENT ON TABLE sys.audit_event IS 'Data-change audit trail';

